import * as http from 'node:http';
async function main(): Promise<void> {
  const srv = http.createServer((req, res) => {
    const h = req.headers;
    res.setHeader('content-type', 'application/json');
    res.end(JSON.stringify({
      method: req.method, url: req.url, version: req.httpVersion, major: req.httpVersionMajor, minor: req.httpVersionMinor,
      ua: h['user-agent'] ?? null, x: String(h['x-one']), missing: h['nope'] === undefined,
      raw: req.rawHeaders.filter((v: string, i: number) => i % 2 === 0 && v.toLowerCase().startsWith('x-')).map((v: string) => v.toLowerCase()), rawLen: req.rawHeaders.length % 2,
      distinct: req.headersDistinct['x-one'] ?? null, aborted: req.aborted, remote: typeof req.socket.remoteAddress,
    }));
  });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const port = (srv.address() as any).port;
  const r = await fetch('http://127.0.0.1:' + port + '/p?q=1', { headers: { 'X-One': '1', 'User-Agent': 'ua1' } });
  console.log(r.status, r.headers.get('content-type'), await r.text());
  srv.close();
}
